from rules import amount


def solve(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}

    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue

        event_id = event.get("id")
        identity = ("id", event_id) if "id" in event else ("anonymous", position)
        revision = event.get("revision", 0)
        previous = winners.get(identity)
        if previous is None or revision >= previous[0]:
            winners[identity] = (revision, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void") is True:
            continue
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = f"{account}|{currency}"
        balances.setdefault(key, 0)
        balances[key] += amount(event, data["rounding"])

    return {"balances": balances}

def _round_dividend(numerator, mode):
    if mode == "floor":
        return numerator // 10000
    if mode == "half_up":
        return (numerator + 5000) // 10000
    raise ValueError(f"unsupported rounding mode: {mode}")


def amount(event, mode):
    base = event["price"] * event.get("quantity", 1)
    discount_bp = min(10000, max(0, event.get("discount_bp", 0)))
    net = _round_dividend(base * (10000 - discount_bp), mode)
    tax = _round_dividend(net * event.get("tax_bp", 0), mode)
    total = net + tax
    if event.get("kind") == "refund":
        return -total
    return total
